const panel=document.createElement('section');panel.className='panel surface-panel';panel.innerHTML=`<div class="section-title"><h2><span>04</span> 物体の3D表面スキャン</h2><span id="surface-state" class="tiny">準備中</span></div><div class="surface-body"><p class="help">上のカメラ1・2を使用します。エピポーラ線上で実画素のRGB領域を照合し、三角測量した観測点を表示します。骨格は求めません。</p><div class="surface-controls"><label>カメラ2の時刻差（秒）<input id="s-offset" type="number" value="16.40" step="0.01"></label><label>カメラ1の時刻<input id="s-time" type="number" value="60" step="0.01"></label><button id="s-seek">同期して移動</button><button id="s-calibrate">現在のA4で配置を取得</button></div><input id="s-timeline" type="range" min="0" max="288" step="0.01" value="60" aria-label="同期動画の再生位置"><p class="help" id="s-times">カメラ2時刻 = カメラ1時刻 ＋16.40秒（音声で再確認できます）</p><div class="surface-controls"><label>背景1の時刻<input id="s-bgA" type="number" value="60" step="0.01"></label><label>背景2の時刻<input id="s-bgB" type="number" value="76.40" step="0.01"></label><button id="s-background">指定時刻を背景として学習</button><button id="s-scan" class="primary">表面をスキャン</button><button id="s-run">連続スキャン</button></div><p class="help">対象のいない時刻を背景に指定します。カメラと背景は固定して扱います。</p><details><summary>照合設定・診断</summary><div class="surface-controls"><label>処理幅<select id="s-size"><option>320</option><option selected>480</option><option>640</option></select></label><label>点間隔<select id="s-step"><option selected>2</option><option>3</option><option>4</option></select></label><label>相関の下限<input id="s-ncc" type="number" value="0.8" step="0.01"></label><label>候補差の下限<input id="s-unique" type="number" value="0.035" step="0.005"></label><label>最小距離m<input id="s-near" type="number" value="0.3" step="0.1"></label><label>最大距離m<input id="s-far" type="number" value="6" step="0.1"></label><label>基準紙1<input id="s-refA" type="number" value="0" min="0"></label><label>基準紙2<input id="s-refB" type="number" value="1" min="0"></label><button id="s-detect">タグと画角を確認</button></div><p class="help">基準紙は上から0, 1…。2映像で同じ実物を選択。正解の対応点を外から与える処理はありません。</p></details><div class="surface-scene-actions"><button id="s-front">正面</button><button id="s-oblique">斜め</button><button id="s-top">上から</button><button id="s-ply">点群PLYを保存</button><button id="s-json">結果を保存</button></div><div id="surface-scene"></div><div id="s-metrics" class="help">未検証。対応の曖昧な場所や見えない裏面は埋めません。</div><div class="surface-pair"><figure><canvas id="s-rectA"></canvas><figcaption>カメラ1：整列画像と採用点</figcaption></figure><figure><canvas id="s-rectB"></canvas><figcaption>カメラ2：整列画像（青は影候補）</figcaption></figure></div><details><summary>処理の記録</summary><pre id="s-log"></pre></details></div>`;
document.querySelector('.main-column').append(panel);const $=id=>document.getElementById('s-'+id),scene=new SurfaceScene(document.getElementById('surface-scene')),worker=new Worker('scan-worker.js?v=20261111-scene-planes-13');
