let serial=0,busy=false,running=false,last=null,lastImages=null,calibration=null,backgroundReady=false;const pending=new Map(),logs=[],captureCanvases=[document.createElement('canvas'),document.createElement('canvas')];const cams=()=>A4App.cameras.slice(0,2),videos=()=>cams().map(c=>c.video);
function log(s){logs.push(`${new Date().toISOString()} ${s}`);$('log').textContent=logs.slice(-120).join('\n');}function status(s){document.getElementById('surface-state').textContent=s;log(s);}
worker.onmessage=e=>{const p=pending.get(e.data.id);if(!p)return;pending.delete(e.data.id);e.data.error?p.reject(Error(e.data.error)):p.resolve(e.data.result);};worker.onerror=e=>{pending.forEach(p=>p.reject(Error(e.message)));pending.clear();status('処理エラー');};
const call=(type,data={})=>new Promise((resolve,reject)=>{const id=++serial;pending.set(id,{resolve,reject});worker.postMessage({id,type,...data});});
const matchingOptions={subpixel:true,completion:true,completionMethod:'photogrammetry',patchRadius:6,stereoBlock:9,alscRadius:10,alscRounds:32,planeRadius:8,planeRefine:false,a4FrontOnly:true,a4FrontMeters:.03};
const opts=()=>({size:+$('size').value,step:+$('step').value,ncc:+$('ncc').value,unique:+$('unique').value,near:+$('near').value,far:+$('far').value,scope:$('scope')?.value||'scene',method:$('method')?.value||'ncc',backend:$('backend')?.value||'webgpu',ruler:+document.getElementById('ruler').value,radial:$('radial')?.checked??true,refs:[+$('refA').value,+$('refB').value],...matchingOptions});
async function guarded(fn){if(busy)throw Error('処理中です');busy=true;try{return await fn();}catch(e){status(e.message);$('metrics').textContent=e.message;throw e;}finally{busy=false;}}
function valid(){if(videos().some(v=>!v.videoWidth))throw Error('上のカメラ1・2に動画を選択してください');}
async function seekOne(v,t){v.pause();if(t<0||t>v.duration)throw Error('動画時刻が範囲外です');if(Math.abs(v.currentTime-t)<.0005&&v.readyState>=2)return;await new Promise((resolve,reject)=>{const timer=setTimeout(()=>{clean();reject(Error('動画シークが完了しません'))},15000);const clean=()=>{clearTimeout(timer);v.removeEventListener('seeked',done);v.removeEventListener('error',fail)};const done=()=>{clean();resolve()};const fail=()=>{clean();reject(Error('動画のデコードに失敗'))};v.addEventListener('seeked',done);v.addEventListener('error',fail);v.currentTime=t;});}
async function seek(t){valid();const vs=videos(),offset=+$('offset').value,min=Math.max(0,-offset),max=Math.min(vs[0].duration,vs[1].duration-offset);t=Math.min(max,Math.max(min,t));await Promise.all([seekOne(vs[0],t),seekOne(vs[1],t+offset)]);cams().forEach(c=>c.dirty=true);$('time').value=t.toFixed(3);$('timeline').min=min;$('timeline').max=max;$('timeline').value=t;$('times').textContent=`カメラ1 ${t.toFixed(3)}秒 / カメラ2 ${(t+offset).toFixed(3)}秒`;return t;}
function capture(i,maxEdge=1920){const v=videos()[i],s=Math.min(1,maxEdge/Math.max(v.videoWidth,v.videoHeight)),c=captureCanvases[i];c.width=Math.round(v.videoWidth*s);c.height=Math.round(v.videoHeight*s);const ctx=c.getContext('2d',{willReadFrequently:true});ctx.drawImage(v,0,0,c.width,c.height);return ctx.getImageData(0,0,c.width,c.height);}
async function captureAt(times,synchronize=false){const cs=cams();if(synchronize&&cs.every(c=>c.kind==='video'&&c.file)){const bTime=await A4Offline.nearestTime(cs[1].file,times[1]);return Promise.all([A4Offline.frameAt(cs[0].file,bTime-(+$('offset').value)),A4Offline.frameAt(cs[1].file,times[1])]);}return Promise.all(times.map(async(t,i)=>{const c=cs[i];return c.kind==='video'&&c.file?A4Offline.frameAt(c.file,t):{image:capture(i),requested:t,seconds:t,errorSeconds:0};}));}
function draw(id,im){const c=$(id);c.width=im.width;c.height=im.height;c.getContext('2d').putImageData(new ImageData(new Uint8ClampedArray(im.data),im.width,im.height),0,0);}
async function calibrate(){return guarded(async()=>{valid();status('A4校正中');const c=await call('calibrate',{images:[capture(0,1920),capture(1,1920)],opts:opts()});calibration=c;backgroundReady=false;scene.setCameras(c.cameras);c.cameras.forEach((lens,i)=>A4App.applyLens(i,lens,lens.reference));status(`カメラ間隔 ${c.baseline.toFixed(3)}m`);$('metrics').textContent=c.cameras.map((x,i)=>`${i+1}: RMS ${x.rms.toFixed(2)}px / 画角 ${x.fov.toFixed(1)}° / 基準紙 ${x.reference}`).join('\n');return c;});}
async function background(){return guarded(async()=>{valid();if(!calibration)throw Error('配置を取得してください');status('背景学習中');const frames=await captureAt([+$('bgA').value,+$('bgB').value]);const r=await call('background',{images:frames.map(f=>f.image),opts:opts()});backgroundReady=true;r.previews.forEach((im,i)=>draw(i?'rectB':'rectA',im));status('背景学習完了');return {backgroundReady:true,frames:frames.map(({image,...f})=>f)};});}
function summary(){if(!last)return null;const {points,colors,uv,faces,labels,pointKinds,classificationSource,previews,accepted,...r}=last;return {...r,pointCount:points.length/3};}
const selectedPoint=i=>!last?.labels||!$('layer')||$('layer').value==='all'||last.labels[i]===+$('layer').value;
function showLayer(){if(!last)return;const chosen=[];for(let i=0;i<last.points.length/3;i++)if(selectedPoint(i))chosen.push(i);scene.selectPoints(new Uint32Array(chosen));const faces=[];for(let i=0;i<(last.faces?.length||0);i+=3){const a=last.faces[i],b=last.faces[i+1],c=last.faces[i+2];if(selectedPoint(a)&&selectedPoint(b)&&selectedPoint(c))faces.push(a,b,c);}scene.setFaces(new Uint32Array(faces));$('layer-summary').textContent=`表示 ${chosen.length} / 全 ${last.points.length/3}点（深度推定 ${last.completion?.estimated||0}点を含む）。背景より手前は人物の確定ラベルではありません。判定保留も保存します。`;}
function rebuildSurface(){if(!last)return;const started=performance.now(),edge=+$('mesh-edge').value;if(!Number.isFinite(edge)||edge<=0)throw Error('接続距離は0より大きい値を指定してください');const mesh=connectSurface(last.points,last.uv,{step:last.options.step,maxEdge:edge,method:$('mesh-method').value});let indices=mesh.indices;if(last.labels){const out=[];for(let i=0;i<indices.length;i+=3){const a=indices[i],b=indices[i+1],c=indices[i+2];if(last.labels[a]===last.labels[b]&&last.labels[a]===last.labels[c])out.push(a,b,c);}indices=new Uint32Array(out);}last.faces=indices;last.surface={...mesh.stats,triangles:indices.length/3,ms:performance.now()-started};showLayer();$('mesh-summary').textContent=`接続 ${last.faces.length/3}面 / 頂点 ${mesh.stats.vertices}点 / ${last.surface.ms.toFixed(1)}ms。面内は未観測の接続推定です。面を消して対応点を確認できます。`;return last.surface;}
