function exportPLY(withFaces=false){if(!last)return;const n=last.points.length/3,faces=withFaces?last.faces:null,lines=['ply','format ascii 1.0','comment Epipolar surface; units meters','comment layer 0=unknown 1=static 2=nearer; faces are unobserved interpolation','comment correspondence_kind 0=stereo 1=plane_ncc_estimate 2=plane_color_estimate 3=least_squares_match 4=joint_depth_estimate 5=piecewise_stereo_estimate 6=slanted_plane_estimate',`element vertex ${n}`,'property float x','property float y','property float z','property uchar red','property uchar green','property uchar blue',...(last.labels?['property uchar layer']:[]),...(last.pointKinds?['property uchar estimated_depth','property uchar correspondence_kind']:[]),...(faces?[`element face ${faces.length/3}`,'property list uchar int vertex_indices']:[]),'end_header'];for(let i=0;i<n;i++)lines.push([...last.points.slice(i*3,i*3+3),...last.colors.slice(i*3,i*3+3),...(last.labels?[last.labels[i]]:[]),...(last.pointKinds?[Number([1,2,4,5,6].includes(last.pointKinds[i])),last.pointKinds[i]]:[])].join(' '));if(faces)for(let i=0;i<faces.length;i+=3)lines.push(`3 ${faces[i]} ${faces[i+1]} ${faces[i+2]}`);download(withFaces?'surface-mesh.ply':'surface.ply',lines.join('\n'),'text/plain');}
