const stereoControls=document.createElement('div');stereoControls.className='surface-controls';stereoControls.innerHTML='<label>同じ紙の組（カメラ1:2）<input id="s-paper-pairs" placeholder="例 0:0, 1:1"></label><label><input type="checkbox" id="s-radial" checked> レンズ歪み（k1）も推定</label><button id="s-stereo">2台を同時校正</button>';$('detect').parentElement.after(stereoControls);$('stereo').onclick=ui(()=>calibrateStereo($('paper-pairs').value.split(',').map(s=>s.trim().split(':').map(Number))));
function invalidate(){running=false;calibration=null;backgroundReady=false;last=null;syncEvidence=null;$('offset').value=0;$('times').textContent='時刻差は未確認です。音声同期を実行するか実測値を入力してください。';A4App.clearStereo();scene.setPoints(new Float32Array(),new Uint8Array());call('reset').catch(e=>status(e.message));status('映像を変更しました。同期と配置を確認してください');}
async function audioSync(){return guarded(async()=>{valid();const signals=[];for(let i=0;i<2;i++){if(!cams()[i].file)throw Error('動画ファイルを選択してください');signals.push(await envelope(cams()[i].file,p=>status(`音声を確認中 ${i+1}/2 ${(p*100).toFixed(0)}%`)));}const r=compare(...signals);syncEvidence={...r,inputs:sourceInfo()};log(JSON.stringify(syncEvidence));$('metrics').textContent=`音声の時刻差候補 ${r.offset.toFixed(2)}秒 / 相関 ${r.score.toFixed(3)} / 区間ごとの差 ${r.spread.toFixed(2)}秒`;if(r.confident){$('offset').value=r.offset;$('bgB').value=(+$('bgA').value+r.offset).toFixed(3);backgroundReady=false;await seek(+$('time').value);status('音声から時刻差を設定しました。映像の動作も確認してください');}else status('音声で同期を確定できません。候補を確認してください');return r;});}
const syncButton=document.createElement('button');syncButton.textContent='音声から時刻差を確認';syncButton.onclick=ui(audioSync);$('seek').after(syncButton);
const matcherControl=document.createElement('label');matcherControl.innerHTML='画素の照合方式<select id="s-method"><option value="ncc">RGB局所相関</option><option value="sgbm" selected>OpenCV StereoSGBM＋RGB確認</option></select>';$('detect').before(matcherControl);$('method').onchange=()=>{backgroundReady=false;status('背景の対応を計算し直してください')};
 $('step').prepend(new Option('1','1'));$('step').value='1';
 $('size').value='640';
const completionControl=document.createElement('label');completionControl.innerHTML='深度の復元<select id="s-depth-mode"><option value="none">実測対応のみ</option><option value="alsc">最小二乗の追加照合</option><option value="photogrammetry" selected>実測対応＋表面推定（検証中）</option></select>';matcherControl.after(completionControl);$('depth-mode').onchange=()=>{matchingOptions.completion=$('depth-mode').value!=='none';matchingOptions.completionMethod=$('depth-mode').value;status('復元方法を変更しました。表面をスキャンしてください');};
const backendControl=document.createElement('label');backendControl.innerHTML='ステレオ照合の実行先<select id="s-backend"><option value="webgpu" selected>WebGPU</option><option value="cpu">CPU（比較用）</option></select>';matcherControl.after(backendControl);$('backend').onchange=()=>{backgroundReady=false;status('実行先を変更しました。背景を学習し直してください')};
async function loadCalibration(value){return guarded(async()=>{const r=await call('import',{value});calibration={...value,...r};backgroundReady=false;last=null;scene.setPoints(new Float32Array(),new Uint8Array());scene.setCameras(r.cameras);A4App.applyStereo(calibration);status('保存済みの2台の校正を読み込みました');return calibration;});}
const calibrationFile=document.createElement('input');calibrationFile.type='file';calibrationFile.accept='.json';calibrationFile.hidden=true;calibrationFile.onchange=ui(async()=>{if(calibrationFile.files[0])await loadCalibration(JSON.parse(await calibrationFile.files[0].text()));});panel.append(calibrationFile);
const loadButton=document.createElement('button');loadButton.textContent='2台の校正を読み込む';loadButton.onclick=()=>calibrationFile.click();$('stereo').after(loadButton);
const saveCalibrationButton=document.createElement('button');saveCalibrationButton.textContent='2台の校正を保存';saveCalibrationButton.onclick=()=>calibration&&download('stereo-calibration.json',JSON.stringify(calibration,null,2),'application/json');loadButton.after(saveCalibrationButton);
function showCorrespondences(){
 if(!last||!lastImages)return;
 for(let ci=0;ci<2;ci++){
  const im=lastImages[ci],canvas=$(ci?'rectB':'rectA');draw(ci?'rectB':'rectA',im);const ctx=canvas.getContext('2d'),c=last.cameras[ci],s=canvas.width/c.width,positions=[];
  for(let i=0;i<last.points.length/3;i++){if(!selectedPoint(i))continue;const p=A4Core.project(Array.from(last.points.slice(i*3,i*3+3)),c,c.K,c.D);if(p){p[0]+=last.stabilization?.[ci]?.originalShift?.[0]||0;p[1]+=last.stabilization?.[ci]?.originalShift?.[1]||0;positions.push([p[0]*s,p[1]*s]);ctx.fillStyle=[1,2,4,5,6].includes(last.pointKinds?.[i])?'rgba(230,150,20,.8)':last.labels?['rgba(255,180,50,.8)','rgba(60,190,255,.8)','rgba(20,220,110,.8)'][last.labels[i]]:'rgba(20,220,110,.7)';ctx.fillRect(p[0]*s,p[1]*s,2,2);}}
  for(let k=0;k<24;k++){const p=positions[Math.floor(k*(positions.length-1)/23)];if(!p)continue;ctx.strokeStyle=ctx.fillStyle=`hsl(${k*137.5%360} 100% 40%)`;ctx.lineWidth=2;ctx.beginPath();ctx.arc(p[0],p[1],5,0,Math.PI*2);ctx.stroke();ctx.font='bold 14px sans-serif';ctx.fillText(k+1,p[0]+5,p[1]-5);}
  canvas.closest('figure').querySelector('figcaption').textContent=`カメラ${ci+1}：同じ番号の実画素対応を確認`;
 }
}
const correspondenceButton=document.createElement('button');correspondenceButton.textContent='対応点を元映像で確認';correspondenceButton.onclick=showCorrespondences;$('json').after(correspondenceButton);
const scopeControl=document.createElement('div');scopeControl.className='surface-controls';scopeControl.innerHTML='<label>復元範囲<select id="s-scope"><option value="scene" selected>壁を含む全シーン → 後から分離</option><option value="foreground">背景・影を除く</option></select></label><label>表示する観測点<select id="s-layer"><option value="all">全観測点</option><option value="1">静止背景と同じ深度</option><option value="2">両視点で背景より手前</option><option value="0">判定保留</option></select></label><span class="help" id="s-layer-summary">RGB照合後に背景深度で分類します。物体が人間かどうかは判別しません。</span>';meshControls.before(scopeControl);$('layer').onchange=()=>{showLayer();showCorrespondences();};$('scope').onchange=()=>{if($('scope').value==='scene'){$('mesh-visible').checked=false;scene.showSurface(false);}status('復元範囲を変更しました。表面をスキャンしてください');};$('mesh-visible').checked=false;scene.showSurface(false);
const frontControl=document.createElement('div');frontControl.className='surface-controls';frontControl.innerHTML='<label><input id="s-a4-front-only" type="checkbox" checked> 基準A4面より手前だけ</label><label>A4面からの距離m<input id="s-a4-front-meters" type="number" min="0" step="0.01" value="0.03"></label>';scopeControl.after(frontControl);$('a4-front-only').onchange=()=>{matchingOptions.a4FrontOnly=$('a4-front-only').checked;status('出力範囲を変更しました。表面をスキャンしてください');};$('a4-front-meters').onchange=()=>{matchingOptions.a4FrontMeters=+$('a4-front-meters').value;status('A4手前の境界を変更しました。表面をスキャンしてください');};
