window.SurfaceScan={seek,audioSync,calibrate,calibrateStereo,calibrateVideo,loadCalibration,showCorrespondences,background,scan,summary,detect,diagnostics:()=>call('diagnostics'),auditGeometry:()=>call('audit',{images:[capture(0,1920),capture(1,1920)],value:calibration}),diagnoseLenses:()=>call('lenses',{images:[capture(0,1920),capture(1,1920)],opts:opts()}),get calibration(){return calibration},get last(){return last},get ready(){return !busy},setOptions(v){for(const [k,x]of Object.entries(v))if($(k))$(k).value=x;else if(k==='subpixel')matchingOptions.subpixel=!!x;else if(['inspectRegion','patchRadius','stereoBlock','completion','completionRadius','completionPropagate','completionMethod','alscRadius','alscRounds','planeRadius','planeConsistency','piecewiseGpuPriors','piecewiseGrowth','piecewisePlaneFit','piecewisePlaneBias','piecewisePlanes','piecewisePriorWeight','bilateralPlanes','bilateralSpatial','bilateralColor','bilateralLambda','bilateralIterations','bilateralLR'].includes(k))matchingOptions[k]=x;},view:v=>scene.view(v),logs};
